package at.hausgarten.service;

import org.json.*;
import java.math.BigDecimal;
import java.util.*;

/** One deterministic review of a draft and its dependencies; never reserves or mutates anything. */
final class InvoiceIssueReviewRules {
    private static JSONObject withoutBinary(JSONObject value)throws Exception {JSONObject result=DriveJournalRules.clean(value);for(String key:new String[]{"pdf_base64","data","full_data","thumbnail_data"})result.remove(key);return result;}
    private static JSONObject find(JSONObject state,String collection,String id)throws Exception {JSONArray rows=state.optJSONArray(collection);for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.optString("id")))return row;}return null;}
    private static void block(JSONArray blockers,String code,String message,String type,String id)throws Exception {JSONObject value=new JSONObject().put("code",code).put("message",message);if(!type.isEmpty())value.put("entity_type",type);if(!id.isEmpty())value.put("id",id);blockers.put(value);}
    private static BigDecimal amount(Object raw)throws Exception {if(raw==null||raw==JSONObject.NULL)throw new IllegalArgumentException();BigDecimal value=new BigDecimal(raw.toString());if(value.signum()<0||value.precision()>24||Math.abs(value.scale())>12)throw new IllegalArgumentException();return value;}
    private static String decimal(BigDecimal value){return value.stripTrailingZeros().toPlainString();}
    private static SortedSet<String> keys(JSONObject value){TreeSet<String> result=new TreeSet<>();for(Iterator<String> names=value.keys();names.hasNext();)result.add(names.next());return result;}
    private static JSONObject object(JSONObject input,String key){JSONObject value=input.optJSONObject(key);return value==null?new JSONObject():value;}
    private static JSONObject authority(JSONObject dependencies)throws Exception {JSONObject source=object(dependencies,"authority"),result=new JSONObject();for(String key:new String[]{"mode","migration_epoch","invoice_authority","installation_id","restore_epoch"})if(source.has(key))result.put(key,source.get(key));return result;}
    static JSONObject capture(JSONObject state,String invoiceId,JSONObject dependencies)throws Exception {
        JSONArray blockers=new JSONArray(),worklogs=new JSONArray(),materials=new JSONArray(),orders=new JSONArray();JSONObject invoice=find(state,"invoices",invoiceId),issuer=state.optJSONObject("business_settings"),recipient=invoice==null?null:find(state,"customers",invoice.optString("customer_id"));String recordHash=invoice==null?"":PixelMcpWriteTools.hash(PixelMcpEntityWriteTools.recordForHash("invoice",invoice));JSONObject authority=authority(dependencies);
        Object version=dependencies.opt("formatVersion");if(!(version instanceof Number)||!version.toString().equals("1"))block(blockers,"INVOICE_REVIEW_DEPENDENCY_VERSION_UNSUPPORTED","Der Ausgabeprüfstand benötigt eine passende Appversion. Keine Ausgabe freigeben.","review","");
        if(invoice==null)block(blockers,"INVOICE_NOT_FOUND","Der Rechnungsentwurf wurde nicht gefunden. Den aktuellen Rechnungsbestand öffnen.","invoice",invoiceId);
        else if(IssuedInvoiceRules.isIssued(invoice)||!invoice.optString("status","Entwurf").equals("Entwurf"))block(blockers,"INVOICE_ALREADY_ISSUED","Dieser Beleg ist kein ausstellbarer Entwurf. Das unveränderliche Original öffnen.","invoice",invoiceId);
        if(issuer==null)block(blockers,"INVOICE_ISSUER_MISSING","Die bestätigten Aussteller- und Nummerneinstellungen fehlen. Firmendaten prüfen.","business_settings","");
        if(invoice!=null&&recipient==null)block(blockers,"INVOICE_RECIPIENT_MISSING","Der gespeicherte Rechnungsempfänger fehlt. Die ursprüngliche Zuordnung ausdrücklich klären.","customer",invoice.optString("customer_id"));
        if(!authority.optString("mode").equals("LOCAL_ACTIVE")||!authority.optString("invoice_authority").equals("RECONCILED"))block(blockers,"INVOICE_AUTHORITY_RECONCILIATION_REQUIRED","Die lokale Rechnungsausgabe ist bis zum aktuellen Beleg- und Nummernabgleich gesperrt.","authority","");
        JSONArray technical=dependencies.optJSONArray("blockers");for(int i=0;technical!=null&&i<technical.length();i++)blockers.put(technical.get(i));
        try{LocalBillingRules.validate(state,new JSONObject().put("formatVersion",1).put("by_invoice",object(dependencies,"worklog_allocations_by_invoice")));}catch(Exception invalid){block(blockers,"LOCAL_BILLING_SOURCE_REVIEW_REQUIRED","Die lokalen Leistungszuordnungen stimmen nicht mit den ausgestellten Belegen überein. Vor einer Ausgabe prüfen.","source_ledger","");}
        JSONObject shown=invoice==null?null:withoutBinary(invoice);if(invoice!=null&&!IssuedInvoiceRules.isIssued(invoice)&&invoice.optString("status","Entwurf").equals("Entwurf"))try{InvoiceDraftRules.normalize(shown,invoice,state);}catch(Exception invalid){shown=withoutBinary(invoice);block(blockers,"INVOICE_DRAFT_REVIEW_REQUIRED",invalid.getMessage()==null?"Der gespeicherte Entwurf benötigt eine erneute fachliche Prüfung.":invalid.getMessage(),"invoice",invoiceId);}JSONObject snapshot=new JSONObject().put("invoice",shown==null?JSONObject.NULL:shown).put("issuer",issuer==null?JSONObject.NULL:withoutBinary(issuer)).put("recipient",recipient==null?JSONObject.NULL:withoutBinary(recipient)).put("worklogs",worklogs).put("materials",materials).put("orders",orders).put("authority",authority);
        if(invoice!=null){
            Map<String,BigDecimal> requestedWork=new TreeMap<>(),requestedMaterial=new TreeMap<>();Set<String> workIds=new TreeSet<>(),materialIds=new TreeSet<>(),orderIds=new TreeSet<>();boolean cancellation=invoice.optString("document_type").equals("cancellation");JSONArray positions=invoice.optJSONArray("positions");
            if(!invoice.optString("order_id").isEmpty())orderIds.add(invoice.getString("order_id"));
            if(positions==null||positions.length()==0)block(blockers,"INVOICE_POSITIONS_MISSING","Der Entwurf benötigt vollständige Leistungspositionen.","invoice",invoiceId);
            for(int i=0;positions!=null&&i<positions.length();i++){
                JSONObject line=positions.optJSONObject(i);if(line==null){block(blockers,"INVOICE_POSITION_INVALID","Eine Rechnungsposition ist nicht lesbar. Den Entwurf prüfen.","invoice",invoiceId);continue;}
                String work=line.optString("worklog_id"),type=line.optString("source_type"),source=line.optString("source_id");if(type.equals("worklog")){if(!work.isEmpty()&&!source.equals(work))block(blockers,"INVOICE_SOURCE_REFERENCE_MISMATCH","Die Leistungsquellen einer Position widersprechen sich.","worklog",source);work=source;}
                if(!cancellation&&!work.isEmpty()){workIds.add(work);addRequested(requestedWork,work,line,"worklog",blockers);}
                if(!cancellation&&type.equals("material_movement")){if(source.isEmpty())block(blockers,"INVOICE_MATERIAL_SOURCE_MISSING","Die Materialposition benötigt eine eindeutige Einsatzquelle.","material_movement","");else{materialIds.add(source);addRequested(requestedMaterial,source,line,"material_movement",blockers);}}
                if(line.isNull("price")||!line.has("price"))block(blockers,"INVOICE_PRICE_MISSING","Ein bestätigter Positionspreis fehlt. Den Entwurf ergänzen.","invoice",invoiceId);
            }
            JSONArray linked=invoice.optJSONArray("worklog_ids");for(int i=0;!cancellation&&linked!=null&&i<linked.length();i++)workIds.add(linked.getString(i));
            for(String id:workIds){JSONObject row=find(state,"worklogs",id);if(row==null){block(blockers,"INVOICE_WORKLOG_MISSING","Eine zugeordnete Arbeitsaufzeichnung fehlt. Den ursprünglichen Leistungsbezug klären.","worklog",id);worklogs.put(new JSONObject().put("id",id).put("record",JSONObject.NULL));continue;}
                if(!row.optString("order_id").isEmpty())orderIds.add(row.getString("order_id"));JSONObject quantity=workQuantity(state,row,dependencies,blockers),entry=new JSONObject().put("id",id).put("record",withoutBinary(row)).put("record_hash",OwnerJournalRules.version(row)).put("requested_quantity_decimal",requestedWork.containsKey(id)?decimal(requestedWork.get(id)):JSONObject.NULL).put("billing_quantity",quantity).put("allocations_by_invoice",allocations(dependencies,"worklog_allocations_by_invoice",id,blockers));worklogs.put(entry);
                checkRequested(requestedWork.get(id),quantity.opt("remaining_decimal"),id,"worklog",blockers);checkSourceCustomer(state,row,"worklog",id,blockers);checkUnits(invoice,id,"worklog","",blockers);if(!invoice.optString("customer_id").equals(BillingRules.recipient(row)))block(blockers,"INVOICE_SOURCE_RECIPIENT_MISMATCH","Arbeitsaufzeichnung und gespeicherter Rechnungsempfänger passen nicht zusammen.","worklog",id);
            }
            JSONObject movements=object(dependencies,"material_movements"),reversals=object(dependencies,"material_reversals");for(String id:materialIds){JSONObject row=movements.optJSONObject(id);if(row==null){block(blockers,"INVOICE_MATERIAL_SOURCE_MISSING","Eine zugeordnete Materialbewegung fehlt. Die Einsatzdokumentation prüfen.","material_movement",id);materials.put(new JSONObject().put("id",id).put("record",JSONObject.NULL));continue;}
                if(!row.optString("order_id").isEmpty())orderIds.add(row.getString("order_id"));String reversed=reversals.optString(id);JSONObject used=allocations(dependencies,"material_allocations_by_invoice",id,blockers);BigDecimal total=null,allocated=sum(used,blockers,"material_movement",id),remaining=null;try{RevierRules.version(row);if(!id.equals(row.optString("id"))||!row.optString("kind").equals("material_movement"))throw new IllegalArgumentException();BigDecimal signed=new BigDecimal(row.getString("quantity_decimal"));if(!row.optString("movement_kind").equals("consume")||signed.signum()>=0)throw new IllegalArgumentException();total=signed.abs();remaining=total.subtract(allocated);if(remaining.signum()<0)throw new IllegalArgumentException();}catch(Exception invalid){remaining=null;block(blockers,"INVOICE_MATERIAL_QUANTITY_REVIEW_REQUIRED","Materialquelle und bereits zugeordnete Mengen müssen geprüft werden.","material_movement",id);}
                if(!reversed.isEmpty())block(blockers,"INVOICE_MATERIAL_SOURCE_REVERSED","Diese Materialbewegung wurde bereits nachvollziehbar gegen gebucht. Eine gültige Quelle wählen.","material_movement",id);
                JSONObject entry=new JSONObject().put("id",id).put("record",withoutBinary(row)).put("record_hash",PixelMcpWriteTools.hash(DriveJournalRules.clean(row))).put("requested_quantity_decimal",requestedMaterial.containsKey(id)?decimal(requestedMaterial.get(id)):JSONObject.NULL).put("allocated_decimal",allocated==null?JSONObject.NULL:decimal(allocated)).put("remaining_decimal",remaining==null?JSONObject.NULL:decimal(remaining)).put("reversal_id",reversed).put("allocations_by_invoice",used);materials.put(entry);checkRequested(requestedMaterial.get(id),entry.opt("remaining_decimal"),id,"material_movement",blockers);checkSourceCustomer(state,row,"material_movement",id,blockers);checkUnits(invoice,id,"material_movement",row.optString("unit"),blockers);for(String document:keys(used))if(!matchesMaterialAllocation(find(state,"invoices",document),id,row.optString("unit"),used.opt(document)))block(blockers,"INVOICE_SOURCE_LEDGER_INVALID","Eine Materialzuordnung stimmt nicht mit dem unveränderlichen ausgestellten Beleg und seiner Positionsmenge überein.","invoice",document);
                try{String payer=row.optString("billing_customer_id");if(payer.isEmpty()){JSONObject site=find(state,"customers",row.optString("customer_id"));if(site!=null)entry.put("billing_customer_context",withoutBinary(site));payer=BillingRules.defaultRecipient(row.getString("customer_id"),row.optString("order_id"),state);}if(!payer.equals(invoice.optString("customer_id")))throw new IllegalArgumentException();}catch(Exception mismatch){block(blockers,"INVOICE_MATERIAL_RECIPIENT_MISMATCH","Materialeinsatz und gespeicherter Rechnungsempfänger müssen ausdrücklich abgeglichen werden.","material_movement",id);}
            }
            for(String id:orderIds){JSONObject row=find(state,"orders",id);if(row==null){block(blockers,"INVOICE_ORDER_MISSING","Ein zugeordneter Auftrag fehlt. Den ursprünglichen Bezug klären.","order",id);orders.put(new JSONObject().put("id",id).put("record",JSONObject.NULL));}else orders.put(new JSONObject().put("id",id).put("record",withoutBinary(row)).put("record_hash",OwnerJournalRules.version(row)));}
            if(!invoice.optString("correction_of").isEmpty()){JSONObject original=find(state,"invoices",invoice.getString("correction_of"));snapshot.put("correction_original",original==null?JSONObject.NULL:withoutBinary(original));if(original==null||!IssuedInvoiceRules.isIssued(original))block(blockers,"INVOICE_CORRECTION_ORIGINAL_MISSING","Der Korrekturbezug benötigt den bestehenden ausgestellten Originalbeleg.","invoice",invoice.getString("correction_of"));}
        }
        JSONObject review=new JSONObject().put("formatVersion",1).put("invoice_id",invoiceId).put("record_hash",recordHash).put("snapshot",snapshot).put("ready",blockers.length()==0).put("blockers",blockers);review.put("context_hash",PixelMcpWriteTools.hash(review));return new JSONObject().put("invoice",invoice==null?JSONObject.NULL:withoutBinary(invoice)).put("record_hash",recordHash).put("issue_review",review);
    }
    private static void addRequested(Map<String,BigDecimal> requested,String id,JSONObject line,String type,JSONArray blockers)throws Exception {try{BigDecimal value=amount(line.opt("quantity"));if(value.signum()==0||requested.containsKey(id))throw new IllegalArgumentException();if(line.has("source_quantity_decimal")&&value.compareTo(amount(line.get("source_quantity_decimal")))!=0)throw new IllegalArgumentException();requested.put(id,value);}catch(Exception invalid){block(blockers,"INVOICE_SOURCE_QUANTITY_REVIEW_REQUIRED","Die Quellenmenge einer Position fehlt, ist doppelt oder widersprüchlich.",type,id);}}
    private static JSONObject allocations(JSONObject dependencies,String name,String source,JSONArray blockers)throws Exception {JSONObject all=object(dependencies,name),result=new JSONObject();for(String invoice:keys(all)){JSONObject row=all.optJSONObject(invoice);if(row==null){block(blockers,"INVOICE_SOURCE_LEDGER_INVALID","Eine lokale Leistungszuordnung ist beschädigt. Keine neue Ausgabe freigeben.","invoice",invoice);result.put(invoice,JSONObject.NULL);continue;}if(row.has(source))result.put(invoice,row.get(source));}return result;}
    private static BigDecimal sum(JSONObject allocations,JSONArray blockers,String type,String id)throws Exception {BigDecimal total=BigDecimal.ZERO;boolean valid=true;for(String invoice:keys(allocations))try{Object raw=allocations.get(invoice);if(!(raw instanceof String))throw new IllegalArgumentException();BigDecimal value=amount(raw);if(value.signum()==0)throw new IllegalArgumentException();total=total.add(value);}catch(Exception invalid){valid=false;block(blockers,"INVOICE_SOURCE_LEDGER_INVALID","Bereits zugeordnete Leistungsmenge ist nicht zuverlässig lesbar.",type,id);}return valid?total:null;}
    private static JSONObject workQuantity(JSONObject state,JSONObject row,JSONObject dependencies,JSONArray blockers)throws Exception {String id=row.getString("id");JSONObject used=allocations(dependencies,"worklog_allocations_by_invoice",id,blockers);BigDecimal allocated=sum(used,blockers,"worklog",id),quantity=null,remaining=null;boolean unknown=false;try{quantity=amount(row.opt("hours"));remaining=quantity.subtract(allocated);if(remaining.signum()<0)throw new IllegalArgumentException();}catch(Exception invalid){remaining=null;block(blockers,"INVOICE_SOURCE_QUANTITY_REVIEW_REQUIRED","Gespeicherte Stunden und bereits zugeordnete Mengen passen nicht zusammen.","worklog",id);}
        JSONArray invoices=state.optJSONArray("invoices");for(int i=0;invoices!=null&&i<invoices.length();i++){JSONObject invoice=invoices.getJSONObject(i);if(IssuedInvoiceRules.isIssued(invoice)&&LocalBillingRules.linked(invoice,id)&&!used.has(invoice.getString("id")))unknown=true;}if(row.optInt("billed",0)!=0&&(remaining==null||remaining.signum()>0))unknown=true;if(unknown){block(blockers,"INVOICE_SOURCE_BILLING_UNCLEAR","Für diese Arbeitsaufzeichnung ist die offene Menge nicht vollständig belegt. Historische Abrechnung prüfen.","worklog",id);remaining=null;}
        for(String invoice:keys(used)){JSONObject original=find(state,"invoices",invoice);if(original==null||!IssuedInvoiceRules.isIssued(original)||!LocalBillingRules.linked(original,id))block(blockers,"INVOICE_SOURCE_LEDGER_INVALID","Eine Leistungszuordnung besitzt keinen passenden ausgestellten Beleg.","invoice",invoice);}
        return new JSONObject().put("formatVersion",1).put("quantity_decimal",quantity==null?JSONObject.NULL:decimal(quantity)).put("allocated_decimal",allocated==null?JSONObject.NULL:decimal(allocated)).put("remaining_decimal",remaining==null?JSONObject.NULL:decimal(remaining)).put("evidence",remaining==null?"billing_unclear":remaining.signum()==0&&allocated.signum()>0?"proven_invoiced":allocated.signum()>0?"partially_invoiced":"marked_open_not_proven");
    }
    private static void checkSourceCustomer(JSONObject state,JSONObject source,String type,String id,JSONArray blockers)throws Exception {if(find(state,"customers",source.optString("customer_id"))==null)block(blockers,"INVOICE_SOURCE_CUSTOMER_MISSING","Der ursprüngliche Einsatzkunde einer Leistungsquelle fehlt. Die Zuordnung klären; keinen Ersatzkunden automatisch übernehmen.",type,id);}
    private static void checkUnits(JSONObject invoice,String id,String type,String expected,JSONArray blockers)throws Exception {JSONArray lines=invoice.optJSONArray("positions");for(int i=0;lines!=null&&i<lines.length();i++){JSONObject line=lines.optJSONObject(i);if(line==null)continue;boolean linked=type.equals("worklog")?(id.equals(line.optString("worklog_id"))||line.optString("source_type").equals("worklog")&&id.equals(line.optString("source_id"))):line.optString("source_type").equals("material_movement")&&id.equals(line.optString("source_id"));if(!linked)continue;String unit=line.optString("unit");if(type.equals("worklog")?!Arrays.asList("h","std","std.","stunde","stunden").contains(unit.toLowerCase(Locale.ROOT)):!unit.equals(expected))block(blockers,"INVOICE_SOURCE_UNIT_REVIEW_REQUIRED","Positions- und Quellenmenge benötigen dieselbe fachliche Einheit. Die Position prüfen.",type,id);}}
    private static boolean matchesMaterialAllocation(JSONObject invoice,String id,String unit,Object raw)throws Exception {try{if(invoice==null||!IssuedInvoiceRules.isIssued(invoice)||!LocalAuthorityRules.ENGINE.equals(object(invoice,"numbering_receipt").optString("authority"))||invoice.optString("local_issue_request").isEmpty()||!(raw instanceof String))return false;BigDecimal expected=amount(raw),snapshot=amount(object(invoice,"local_material_source_allocations").opt(id));if(expected.signum()<=0||expected.compareTo(snapshot)!=0)return false;JSONArray lines=invoice.optJSONArray("positions");int count=0;for(int i=0;lines!=null&&i<lines.length();i++){JSONObject line=lines.optJSONObject(i);if(line==null||!line.optString("source_type").equals("material_movement")||!id.equals(line.optString("source_id")))continue;count++;if(!unit.equals(line.optString("unit"))||expected.compareTo(amount(line.opt("quantity")))!=0||line.has("source_quantity_decimal")&&expected.compareTo(amount(line.get("source_quantity_decimal")))!=0)return false;}return count==1;}catch(Exception invalid){return false;}}
    private static void checkRequested(BigDecimal requested,Object remaining,String id,String type,JSONArray blockers)throws Exception {try{if(requested==null||requested.signum()<=0||requested.compareTo(amount(remaining))>0)throw new IllegalArgumentException();}catch(Exception invalid){block(blockers,"INVOICE_SOURCE_QUANTITY_EXCEEDED","Die gewünschte Positionsmenge überschreitet den belegten Rest oder ist noch ungeklärt.",type,id);}}
    static void requireCurrent(JSONObject review,String expectedContextHash)throws Exception {Object version=review.opt("formatVersion");if(!(version instanceof Number)||!version.toString().equals("1")||expectedContextHash==null||!expectedContextHash.matches("[0-9a-f]{64}"))throw new PixelMcpWriteTools.Rejected("INVOICE_REVIEW_CONTEXT_REQUIRED","Die vollständige lokale Ausgabeprüfung neu öffnen und ausdrücklich bestätigen.");if(!expectedContextHash.equals(review.optString("context_hash")))throw new PixelMcpWriteTools.Rejected("WRITE_CONFLICT","Entwurf, Aussteller, Empfänger oder Leistungsquellen haben sich seit der Prüfung geändert. Den aktuellen Ausgabeentwurf erneut prüfen.");if(!review.optBoolean("ready")||review.optJSONArray("blockers")==null||review.getJSONArray("blockers").length()!=0)throw new PixelMcpWriteTools.Rejected("INVOICE_REVIEW_BLOCKED",review.optJSONArray("blockers")!=null&&review.getJSONArray("blockers").length()>0?review.getJSONArray("blockers").getJSONObject(0).optString("message","Die Ausgabeprüfung ist noch nicht vollständig."):"Die Ausgabeprüfung ist noch nicht vollständig.");}
    private InvoiceIssueReviewRules(){}
}
